  EXPECT_EQ_INT(0, *offset);
  EXPECT_EQ_STR("testA", token->str);
  sfree(offset);
  sfree(token->str);
  sfree(token);

  ret = c_avl_pick(tokens, (void **)&offset, (void **)&token);
  OK(ret != 0);

